def generate(seed):
    r = random.Random(seed)
    while True:
        H = r.randrange(9, 13); W = r.randrange(11, 17)
        g = [['.'] * W for _ in range(H)]
        cells = [(y, x) for y in range(H) for x in range(W)]
        r.shuffle(cells)
        p0 = r.choice([0.12, 0.16, 0.20]); p1 = r.choice([0.35, 0.45, 0.55])
        for y, x in cells:
            k = 0
            for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                a, b = y + dy, x + dx
                if 0 <= a < H and 0 <= b < W and g[a][b] == '#':
                    k += 1
            if k == 0:
                if r.random() < p0:
                    g[y][x] = '#'
            elif k == 1:
                if r.random() < p1:
                    g[y][x] = '#'
        v = sum(row.count('#') for row in g)
        if v >= 8:
            return '\n'.join(''.join(row) for row in g)

