def solve(clue):
    g = clue.split()
    H = len(g); W = len(g[0])
    seen = set(); n = 0
    for y in range(H):
        for x in range(W):
            if g[y][x] == '#' and (y, x) not in seen:
                n += 1
                st = [(y, x)]; seen.add((y, x))
                while st:
                    a, b = st.pop()
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        u, v = a + dy, b + dx
                        if 0 <= u < H and 0 <= v < W and g[u][v] == '#' and (u, v) not in seen:
                            seen.add((u, v)); st.append((u, v))
    return str(n)

